class Solution {
public:
    int maxSum(std::vector<std::vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size();
        int best = 0;
        for (int r = 0; r < m - 2; r++) {
            for (int c = 0; c < n - 2; c++) {
                int cur = grid[r][c] + grid[r][c + 1] + grid[r][c + 2]
                        + grid[r + 1][c + 1]
                        + grid[r + 2][c] + grid[r + 2][c + 1] + grid[r + 2][c + 2];
                best = std::max(best, cur);
            }
        }
        return best;
    }
};

class Solution {
    public int maxSum(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        int best = 0;
        for (int r = 0; r < m - 2; r++) {
            for (int c = 0; c < n - 2; c++) {
                int cur = grid[r][c] + grid[r][c + 1] + grid[r][c + 2]
                        + grid[r + 1][c + 1]
                        + grid[r + 2][c] + grid[r + 2][c + 1] + grid[r + 2][c + 2];
                if (cur > best) best = cur;
            }
        }
        return best;
    }
}

